package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// API66 owned prefix fixtures admitted by SF180 and SF182.
func TestCustomMetadataPrefixAPI66Proof(t *testing.T) {
	for _, tc := range []struct {
		name  string
		files map[string]string
	}{
		{name: "singleton", files: map[string]string{
			"force-app/main/default/classes/GladeMetadataPrefix66Proof.cls":                        "@IsTest private class GladeMetadataPrefix66Proof {\n @IsTest static void describePrefixAndSyntheticIdType() {\n  Map<String,Object> result = new Map<String,Object>();\n  Schema.SObjectType expectedType=GladePrefix66__mdt.SObjectType;\n  String prefix=expectedType.getDescribe().getKeyPrefix();\n  result.put('describePrefix',prefix);\n  result.put('describeName',expectedType.getDescribe().getName());\n  String raw=prefix+'00000000000000E';\n  result.put('constructedText',raw);\n  result.put('hardcodedText','m0000000000000000E');\n  try {\n   GladePrefix66__mdt row=new GladePrefix66__mdt(Id=raw,Label='Owned mock',DeveloperName='Owned_mock');\n   result.put('constructorSucceeded',true);\n   result.put('storedId',String.valueOf(row.Id));\n   result.put('storedEqualsConstructed',String.valueOf(row.Id)==raw);\n   result.put('storedEqualsHardcoded',String.valueOf(row.Id)=='m0000000000000000E');\n   try {\n    Schema.SObjectType actualType=row.Id.getSObjectType();\n    result.put('idTypeName',actualType.getDescribe().getName());\n    result.put('idTypeMatchesOwned',actualType==expectedType);\n   } catch(Exception error) {\n    result.put('idTypeError',error.getTypeName());\n    result.put('idTypeMessage',error.getMessage());\n   }\n  } catch(Exception error) {\n   result.put('constructorSucceeded',false);\n   result.put('constructorError',error.getTypeName());\n   result.put('constructorMessage',error.getMessage());\n  }\n  try {\n   Id hardcoded='m0000000000000000E';\n   Schema.SObjectType hardcodedType=hardcoded.getSObjectType();\n   result.put('hardcodedTypeName',hardcodedType.getDescribe().getName());\n   result.put('hardcodedTypeMatchesOwned',hardcodedType==expectedType);\n  } catch(Exception error) {\n   result.put('hardcodedTypeError',error.getTypeName());\n   result.put('hardcodedTypeMessage',error.getMessage());\n  }\n  System.assertEquals(12,result.size(),'exact observed result shape');\n  System.assertEquals('m00',result.get('describePrefix'),'describePrefix');\n  System.assertEquals('GladePrefix66__mdt',result.get('describeName'),'describeName');\n  System.assertEquals('m0000000000000000E',result.get('constructedText'),'constructedText');\n  System.assertEquals('m0000000000000000E',result.get('hardcodedText'),'hardcodedText');\n  System.assertEquals(true,result.get('constructorSucceeded'),'constructorSucceeded');\n  System.assertEquals('m0000000000000000E',result.get('storedId'),'storedId');\n  System.assertEquals(true,result.get('storedEqualsConstructed'),'storedEqualsConstructed');\n  System.assertEquals(true,result.get('storedEqualsHardcoded'),'storedEqualsHardcoded');\n  System.assertEquals('GladePrefix66__mdt',result.get('idTypeName'),'idTypeName');\n  System.assertEquals(true,result.get('idTypeMatchesOwned'),'idTypeMatchesOwned');\n  System.assertEquals('GladePrefix66__mdt',result.get('hardcodedTypeName'),'hardcodedTypeName');\n  System.assertEquals(true,result.get('hardcodedTypeMatchesOwned'),'hardcodedTypeMatchesOwned');\n }\n}\n",
			"force-app/main/default/classes/GladeMetadataPrefix66Proof.cls-meta.xml":               "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>66.0</apiVersion><status>Active</status></ApexClass>\n",
			"force-app/main/default/objects/GladePrefix66__mdt/GladePrefix66__mdt.object-meta.xml": "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><label>Glade Prefix 66</label><pluralLabel>Glade Prefix 66 Types</pluralLabel><visibility>Public</visibility></CustomObject>\n",
			"sfdx-project.json": "{\"namespace\": \"\", \"sourceApiVersion\": \"66.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}",
		}},
		{name: "pair", files: map[string]string{
			"force-app/main/default/classes/GladeMetadataPrefixPair66Proof.cls":                              "@IsTest private class GladeMetadataPrefixPair66Proof {\n private static Map<String,Object> observe(Schema.SObjectType expectedType) {\n  Map<String,Object> result=new Map<String,Object>();\n  result.put('name',expectedType.getDescribe().getName());\n  String prefix=expectedType.getDescribe().getKeyPrefix();\n  result.put('prefix',prefix);\n  String raw=prefix+'00000000000000E';\n  result.put('raw',raw);\n  try {\n   SObject row;\n   if(expectedType==GladePrefixPairA66__mdt.SObjectType) row=new GladePrefixPairA66__mdt(Id=raw);\n   else row=new GladePrefixPairB66__mdt(Id=raw);\n   result.put('stored',String.valueOf(row.Id));\n   result.put('recordTypeName',row.getSObjectType().getDescribe().getName());\n   try {\n    Schema.SObjectType actualType=row.Id.getSObjectType();\n    result.put('idTypeName',actualType.getDescribe().getName());\n    result.put('matchesDeclared',actualType==expectedType);\n   } catch(Exception error) {\n    result.put('idTypeError',error.getTypeName());\n    result.put('idTypeMessage',error.getMessage());\n   }\n  } catch(Exception error) {\n   result.put('constructorError',error.getTypeName());\n   result.put('constructorMessage',error.getMessage());\n  }\n  return result;\n }\n @IsTest static void twoTypesForwardAndReverse() {\n  List<Object> rows=new List<Object>{\n   observe(GladePrefixPairA66__mdt.SObjectType),\n   observe(GladePrefixPairB66__mdt.SObjectType),\n   observe(GladePrefixPairB66__mdt.SObjectType),\n   observe(GladePrefixPairA66__mdt.SObjectType)\n  };\n  System.assertEquals(4,rows.size());\n  Map<String,Object> row0=(Map<String,Object>)rows[0];\n  System.assertEquals(7,row0.size(),'row0 shape');\n  System.assertEquals(true,row0.get('matchesDeclared'),'row0:matchesDeclared');\n  System.assertEquals('GladePrefixPairA66__mdt',row0.get('idTypeName'),'row0:idTypeName');\n  System.assertEquals('GladePrefixPairA66__mdt',row0.get('recordTypeName'),'row0:recordTypeName');\n  System.assertEquals('m0000000000000000E',row0.get('stored'),'row0:stored');\n  System.assertEquals('m0000000000000000E',row0.get('raw'),'row0:raw');\n  System.assertEquals('m00',row0.get('prefix'),'row0:prefix');\n  System.assertEquals('GladePrefixPairA66__mdt',row0.get('name'),'row0:name');\n  Map<String,Object> row1=(Map<String,Object>)rows[1];\n  System.assertEquals(7,row1.size(),'row1 shape');\n  System.assertEquals(true,row1.get('matchesDeclared'),'row1:matchesDeclared');\n  System.assertEquals('GladePrefixPairB66__mdt',row1.get('idTypeName'),'row1:idTypeName');\n  System.assertEquals('GladePrefixPairB66__mdt',row1.get('recordTypeName'),'row1:recordTypeName');\n  System.assertEquals('m0100000000000000E',row1.get('stored'),'row1:stored');\n  System.assertEquals('m0100000000000000E',row1.get('raw'),'row1:raw');\n  System.assertEquals('m01',row1.get('prefix'),'row1:prefix');\n  System.assertEquals('GladePrefixPairB66__mdt',row1.get('name'),'row1:name');\n  Map<String,Object> row2=(Map<String,Object>)rows[2];\n  System.assertEquals(7,row2.size(),'row2 shape');\n  System.assertEquals(true,row2.get('matchesDeclared'),'row2:matchesDeclared');\n  System.assertEquals('GladePrefixPairB66__mdt',row2.get('idTypeName'),'row2:idTypeName');\n  System.assertEquals('GladePrefixPairB66__mdt',row2.get('recordTypeName'),'row2:recordTypeName');\n  System.assertEquals('m0100000000000000E',row2.get('stored'),'row2:stored');\n  System.assertEquals('m0100000000000000E',row2.get('raw'),'row2:raw');\n  System.assertEquals('m01',row2.get('prefix'),'row2:prefix');\n  System.assertEquals('GladePrefixPairB66__mdt',row2.get('name'),'row2:name');\n  Map<String,Object> row3=(Map<String,Object>)rows[3];\n  System.assertEquals(7,row3.size(),'row3 shape');\n  System.assertEquals(true,row3.get('matchesDeclared'),'row3:matchesDeclared');\n  System.assertEquals('GladePrefixPairA66__mdt',row3.get('idTypeName'),'row3:idTypeName');\n  System.assertEquals('GladePrefixPairA66__mdt',row3.get('recordTypeName'),'row3:recordTypeName');\n  System.assertEquals('m0000000000000000E',row3.get('stored'),'row3:stored');\n  System.assertEquals('m0000000000000000E',row3.get('raw'),'row3:raw');\n  System.assertEquals('m00',row3.get('prefix'),'row3:prefix');\n  System.assertEquals('GladePrefixPairA66__mdt',row3.get('name'),'row3:name');\n }\n}\n",
			"force-app/main/default/classes/GladeMetadataPrefixPair66Proof.cls-meta.xml":                     "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>66.0</apiVersion><status>Active</status></ApexClass>\n",
			"force-app/main/default/objects/GladePrefixPairA66__mdt/GladePrefixPairA66__mdt.object-meta.xml": "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><label>GladePrefixPairA66</label><pluralLabel>GladePrefixPairA66 Types</pluralLabel><visibility>Public</visibility></CustomObject>\n",
			"force-app/main/default/objects/GladePrefixPairB66__mdt/GladePrefixPairB66__mdt.object-meta.xml": "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><label>GladePrefixPairB66</label><pluralLabel>GladePrefixPairB66 Types</pluralLabel><visibility>Public</visibility></CustomObject>\n",
			"sfdx-project.json": "{\"namespace\": \"\", \"sourceApiVersion\": \"66.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}",
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			root := t.TempDir()
			for path, content := range tc.files {
				writeFile(t, filepath.Join(root, path), content)
			}
			run := Run(loadTestIndex(t, root), Options{NoDiskCache: true})
			data, _ := json.Marshal(run)
			if got := run.Summary(); got.Total != 1 || got.Passed != 1 || got.Errors != 0 || got.Skipped != 0 {
				t.Fatalf("prefix proof: %s", data)
			}
		})
	}
}
